func main() {
        if len(os.Args) < 2 {
                fmt.Fprintf(os.Stderr, "flowctl: usage: flowctl run --config <path> [--strict]\n")
                os.Exit(2)
        }

        if os.Args[1] != "run" {
                fmt.Fprintf(os.Stderr, "flowctl: unknown command %q\n", os.Args[1])
                os.Exit(2)
        }

        args := os.Args[2:]
        configPath := ""
        strict := false

        for i := 0; i < len(args); i++ {
                arg := args[i]
                switch {
                case arg == "--config":
                        if i+1 >= len(args) {
                                fmt.Fprintf(os.Stderr, "flowctl: --config requires a value\n")
                                os.Exit(2)
                        }
                        configPath = args[i+1]
                        i++
                case strings.HasPrefix(arg, "--config="):
                        configPath = strings.TrimPrefix(arg, "--config=")
                case arg == "--strict":
                        strict = true
                default:
                        fmt.Fprintf(os.Stderr, "flowctl: unknown flag %q\n", arg)
                        os.Exit(2)
                }
        }

        if configPath == "" {
                fmt.Fprintf(os.Stderr, "flowctl: --config is required\n")
                os.Exit(2)
        }

        cfg, err := config.Load(configPath)
        if err != nil {
                fmt.Fprintf(os.Stderr, "flowctl: %v\n", err)
                os.Exit(1)
        }
        cfg.Strict = strict

        stats, err := pipeline.Run(cfg)
        if err != nil {
                fmt.Fprintf(os.Stderr, "flowctl: %v\n", err)
                os.Exit(1)
        }

        fmt.Fprintf(os.Stderr, "flowctl: processed=%d emitted=%d dropped_nonnumeric=%d dropped_missing=%d\n",
                stats.Processed, stats.Emitted, stats.DroppedNonNumeric, stats.DroppedMissing)
}
