type dedupWhen struct {
        column string
        op      string
        value   string
}

type dedupKey struct {
        pos      int
        record   *record.Record
        value    string
        ok       bool
        sentinel bool
        finite   bool
        num      float64
}

type DedupStage struct {
        idx       int
        by        []string
        keep      string
        on        string
        fallback  string
        when      *dedupWhen
}

func (s *DedupStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
        out := make([]*record.Record, 0, len(in))
        groups := map[string]*dedupGroup{}
        var groupOrder []*dedupGroup

        for pos, r := range in {
                if s.when != nil && !s.matchesWhen(r) {
                        out = append(out, r)
                        continue
                }

                key, err := s.groupKey(r, pos)
                if err != nil {
                        fmt.Fprintf(stderr, "flowctl: dedup: %v\n", err)
                        return nil, err
                }

                g, ok := groups[key]
                if !ok {
                        g = &dedupGroup{key: key}
                        groups[key] = g
                        groupOrder = append(groupOrder, g)
                }
                g.items = append(g.items, dedupItem{pos: pos, r: r})
        }

        for _, g := range groupOrder {
                survivor, err := s.pickSurvivor(g, stderr)
                if err != nil {
                        return nil, err
                }
                if survivor == nil {
                        continue
                }
                g.survivor = survivor
        }

        for _, r := range out {
                _ = r
        }
        _ = groupOrder

        return s.collectOutput(in, groups, groupOrder)
}

type dedupGroup struct {
        key      string
        items    []dedupItem
        survivor *dedupItem
}

type dedupItem struct {
        pos int
        r   *record.Record
}

func (s *DedupStage) matchesWhen(r *record.Record) bool {
        v, ok := r.Get(s.when.column)
        if !ok {
                return false
        }
        switch s.when.op {
        case "==":
                return v == s.when.value
        case "!=":
                return v != s.when.value
        default:
                left, err := parseFloat(v)
                if err != nil {
                        return false
                }
                right, err := parseFloat(s.when.value)
                if err != nil {
                        return false
                }
                return compareFloats(left, s.when.op, right)
        }
}

func (s *DedupStage) groupKey(r *record.Record, pos int) (string, error) {
        parts := make([]string, len(s.by)*2)
        for i, col := range s.by {
                v, ok := r.Get(col)
                if !ok {
                        return "", fmt.Errorf("missing by column %s", col)
                }
                parts[i*2] = col
                parts[i*2+1] = v
        }
        return strings.Join(parts, "\x00"), nil
}

func (s *DedupStage) pickSurvivor(g *dedupGroup, stderr io.Writer) (*dedupItem, error) {
        switch s.keep {
        case "first":
                return &g.items[0], nil
        case "last":
                return &g.items[len(g.items)-1], nil
        case "unique":
                if len(g.items) == 1 {
                        return &g.items[0], nil
                }
                return nil, nil
        case "min", "max":
                return s.pickNumeric(g, stderr)
        }
        return nil, nil
}

func (s *DedupStage) pickNumeric(g *dedupGroup, stderr io.Writer) (*dedupItem, error) {
        var best *dedupItem
        var bestNum float64
        bestSet := false

        for i := range g.items {
                item := &g.items[i]
                v, ok := s.onValue(item.r)
                if !ok || v == "" {
                        continue
                }
                f, err := parseFloat(v)
                if err != nil {
                        fmt.Fprintf(stderr, "flowctl: dedup: column %s value %q is not a number\n", s.on, v)
                        return nil, fmt.Errorf("column %s value %q is not a number", s.on, v)
                }
                if !bestSet {
                        best = item
                        bestNum = f
                        bestSet = true
                        continue
