                        }
                }
        }

        if best != nil {
                return best, nil
        }

        if s.fallback == "last" {
                return &g.items[len(g.items)-1], nil
        }
        return &g.items[0], nil
}

func (s *DedupStage) onValue(r *record.Record) (string, bool) {
        return r.Get(s.on)
}

func (s *DedupStage) isBetterNumeric(candidate, current float64) bool {
        if s.keep == "min" {
                return candidate < current
        }
        return candidate > current
}

func (s *DedupStage) collectOutput(in []*record.Record, groups map[string]*dedupGroup, groupOrder []*dedupGroup) ([]*record.Record, error) {
        survivorsByPos := map[int]*record.Record{}
        for _, g := range groupOrder {
                if g.survivor == nil {
                        continue
                }
                survivorsByPos[g.survivor.pos] = g.survivor.r
