		}
		if fb == "" {
			return nil, fmt.Errorf("config: dedup: fallback must be first or last")
		}
		fallback = fb
	}
	if keep == "min" || keep == "max" {
		if fallback != "first" && fallback != "last" {
			return nil, fmt.Errorf("config: dedup: fallback must be first or last")
		}
	} else if fallbackPresent {
		return nil, fmt.Errorf("config: dedup: fallback is only allowed for keep min or max")
	}

	var when *dedupWhen
	if whenRaw, ok := sm["when"]; ok {
		whenMap, ok := whenRaw.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("config: dedup: when must be a mapping")
		}
		column, ok := getString(whenMap, "column")
		if !ok || column == "" {
			return nil, fmt.Errorf("config: dedup: when.column is required")
		}
		op, ok := getString(whenMap, "op")
		if !ok || op == "" {
			return nil, fmt.Errorf("config: dedup: when.op is required")
		}
		switch op {
		case "==", "!=", ">", ">=", "<", "<=":
		default:
			return nil, fmt.Errorf("config: dedup: when.op is invalid")
		}
		value, ok := getString(whenMap, "value")
		if !ok {
			return nil, fmt.Errorf("config: dedup: when.value is required")
		}
		when = &dedupWhen{column: column, op: op, value: value}
	}

	return &DedupStage{idx: idx, by: by, keep: keep, on: on, fallback: fallback, when: when}, nil
}
